import java.security.KeyStore
import java.security.MessageDigest
import java.util.Properties

plugins {
    id("com.android.application")
    // The Flutter Gradle Plugin must be applied after the Android and Kotlin Gradle plugins.
    id("dev.flutter.flutter-gradle-plugin")
}

// Signing identity lives outside the checkout and is never generated by a build.
val releaseSigningPropertiesFile = file(
    providers.environmentVariable("CS_ANDROID_SIGNING_PROPERTIES").orNull
        ?: "${System.getProperty("user.home")}/.config/lexicon-cs/signing.properties"
)
val releaseSigningProperties = Properties().apply {
    if (releaseSigningPropertiesFile.isFile) {
        releaseSigningPropertiesFile.inputStream().use { load(it) }
    }
}
fun releaseSigningProperty(name: String): String =
    releaseSigningProperties.getProperty(name)?.takeIf { it.isNotBlank() }
        ?: throw GradleException("Missing $name in the release signing properties file")

android {
    namespace = "info.typikon.cs"
    compileSdk = flutter.compileSdkVersion
    ndkVersion = flutter.ndkVersion

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    defaultConfig {
        // TODO: Specify your own unique Application ID (https://developer.android.com/studio/build/application-id.html).
        applicationId = "info.typikon.cs"
        // You can update the following values to match your application needs.
        // For more information, see: https://flutter.dev/to/review-gradle-config.
        minSdk = flutter.minSdkVersion
        targetSdk = flutter.targetSdkVersion
        versionCode = flutter.versionCode
        versionName = flutter.versionName
    }

    signingConfigs {
        create("release") {
            if (releaseSigningPropertiesFile.isFile) {
                storeFile = file(releaseSigningProperty("storeFile"))
                storePassword = releaseSigningProperty("storePassword")
                keyAlias = releaseSigningProperty("keyAlias")
                keyPassword = releaseSigningProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            signingConfig = signingConfigs.getByName("release")
        }
    }
}

kotlin {
    compilerOptions {
        jvmTarget = org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17
    }
}

flutter {
    source = "../.."
}

// A missing key must fail the release, never silently change its identity.
val checkReleaseSigning = tasks.register("checkReleaseSigning") {
    doLast {
        if (!releaseSigningPropertiesFile.isFile) {
            throw GradleException(
                "Release signing is not configured. Restore ~/.config/lexicon-cs/signing.properties " +
                    "or set CS_ANDROID_SIGNING_PROPERTIES. Do not generate a replacement key."
            )
        }
        val keystoreFile = file(releaseSigningProperty("storeFile"))
        if (!keystoreFile.isFile) {
            throw GradleException("The permanent release keystore is missing. Restore the original key.")
        }
        val keystore = KeyStore.getInstance("JKS")
        keystoreFile.inputStream().use {
            keystore.load(it, releaseSigningProperty("storePassword").toCharArray())
        }
        val certificate = keystore.getCertificate(releaseSigningProperty("keyAlias"))
            ?: throw GradleException("The permanent release certificate is missing.")
        val fingerprint = MessageDigest.getInstance("SHA-256").digest(certificate.encoded)
            .joinToString("") { "%02x".format(it) }
        if (fingerprint != "efbd5403c1bf73c63e8feac9f95b71b2231c96e7d39c8f2be6a153089a8398f8") {
            throw GradleException("Unexpected release certificate. Restore the original Lexicon CS key.")
        }
    }
}
tasks.matching {
    it.name in setOf("preReleaseBuild", "validateSigningRelease", "packageRelease", "signReleaseBundle")
}.configureEach {
    dependsOn(checkReleaseSigning)
}
